import { Fragment } from 'react';
import { ColorDot, Icon } from '@studio/ui';
import type { IconName } from '@studio/ui';
import type { BootstrapDto, TaskDto } from '@studio/contracts/api';
import { recurrences } from '@studio/contracts/api';
import { AssigneeField, TaskDateField, TaskDependenciesField, TaskEstimateField, TaskLabelsField, TaskPriorityField, TaskProjectField, TaskRecurrenceField, TaskStatusField } from '../fields';
import { TaskLabel } from '../atoms';
import { MemberIdentity } from '../../people/MemberIdentity';
import type { TaskFieldValues, TaskFieldPatch } from '../field-types';
import { useDataRuntime } from '../../../data/context';
export interface TaskPropertyGridProps { value: TaskFieldValues; data: BootstrapDto; tasks: readonly TaskDto[]; onPatch: (patch: TaskFieldPatch) => Promise<boolean> | boolean; openField: keyof TaskFieldValues | null; onOpenFieldChange: (field: keyof TaskFieldValues | null) => void; full?: boolean; form?: boolean; taskId?: TaskDto['id']; disabled?: boolean; error?: string }
export function TaskPropertyGrid({ value, data, tasks, onPatch, openField, onOpenFieldChange, full, form, taskId, disabled, error }: TaskPropertyGridProps) {
 const { clock } = useDataRuntime(), projects = data.projects.filter(item => item.access === 'allowed').map(item => item.project);
 function control<K extends keyof TaskFieldValues>(field: K) { return { value: value[field], onChange: (next: TaskFieldValues[K]) => onPatch(field === 'dueDate' && taskId && typeof next === 'string' && value.startDate && String(value.startDate) > String(next) ? { dueDate: next as TaskDto['dueDate'], startDate: next as TaskDto['startDate'] } : { [field]: next }), open: openField === field, onOpenChange: (open: boolean) => onOpenFieldChange(open ? field : null), disabled: !!disabled, error, presentation: form ? 'form-chip' as const : 'drawer-property' as const, ...(form ? { triggerClassName: 'inline-flex h-[26px] max-w-full items-center gap-[6px] whitespace-nowrap rounded-sm px-[7px] text-sm text-foreground transition-[background] source-hover:bg-surface-2' } : {}) }; }
 const project = projects.find(p => p.id === value.projectId), member = data.members.find(m => m.id === value.assigneeId) ?? null, fmt = (date: string) => new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' }).format(new Date(`${date}T00:00:00Z`));
 const pill = 'inline-flex min-h-[26px] max-w-full items-center gap-[6px] whitespace-nowrap rounded-sm px-[7px] text-sm transition-[background] source-hover:bg-surface-2';
 const entries = [
 { key: 'status', label: 'Status', icon: 'circle-dot', field: <TaskStatusField {...control('status')} triggerLabel="Status" /> },
 { key: 'priority', label: 'Priority', icon: 'signal-high', field: <TaskPriorityField {...control('priority')} /> },
 { key: 'assignee', label: 'Assignee', icon: 'user', field: <AssigneeField {...control('assigneeId')} members={data.members} currentMemberId={data.currentMember.id} trigger={form ? <><MemberIdentity member={member} avatarOnly className="static!" />{member?.name ?? 'Assignee'}</> : <MemberIdentity member={member} className="static!" />} /> },
 { key: 'due', label: 'Due date', icon: 'calendar', field: <TaskDateField {...control('dueDate')} field="dueDate" today={clock.today()} weekStart={data.preferences.weekStart} overdue={value.status !== 'done' && !!value.dueDate && value.dueDate < clock.today()} {...(form ? { trigger: <><Icon name="calendar" size={13} />{value.dueDate ? `Due ${fmt(value.dueDate)}` : 'Due date'}</> } : {})} /> },
 { key: 'start', label: 'Start date', icon: 'calendar-arrow-up', field: <TaskDateField {...control('startDate')} field="startDate" today={clock.today()} weekStart={data.preferences.weekStart} trigger={<><Icon name={form ? 'calendar-arrow-up' : 'calendar'} size={13} />{value.startDate ? `${form ? 'Starts ' : ''}${fmt(value.startDate)}` : form ? 'Start date' : 'Set date'}</>} /> },
 { key: 'project', label: 'Project', icon: 'folder', field: <TaskProjectField {...control('projectId')} projects={projects} {...(form ? { trigger: <><ColorDot className="size-2! rounded-[3px]!" color={project?.color ?? 'var(--text-3)'} />{project?.name ?? 'Project'}</> } : {})} /> },
 { key: 'labels', label: 'Labels', icon: 'tag', field: <TaskLabelsField {...control('labelIds')} triggerClassName={`${pill} flex-wrap whitespace-normal ${form ? 'h-[26px] py-0' : 'py-[3px]'} ${form ? 'border border-solid border-border' : ''} ${!value.labelIds.length && !form ? 'text-muted' : 'text-foreground'}`} trigger={value.labelIds.length ? <>{value.labelIds.map(id => <TaskLabel key={id} id={id} />)}</> : <><Icon name="tag" size={13} />{form ? 'Labels' : 'Add labels'}</>} /> },
 { key: 'repeat', label: 'Repeat', icon: 'repeat', field: <TaskRecurrenceField {...control('recurrence')} triggerClassName={`${pill} ${!value.recurrence && !form ? 'text-muted' : ''}`} trigger={<><Icon name="repeat" size={13} />{recurrences.find(row => row.id === value.recurrence)?.name ?? (form ? 'Repeat' : 'Does not repeat')}</>} /> },
 { key: 'estimate', label: 'Estimate', icon: 'timer', field: <TaskEstimateField {...control('estimate')} trigger={<><Icon name="timer" size={13} />{value.estimate ?? 'Add estimate'}</>} /> },
 { key: 'deps', label: 'Blocked by', icon: 'git-branch', field: <TaskDependenciesField {...control('dependencyIds')} tasks={tasks} projectId={value.projectId} {...(taskId ? { taskId } : {})} triggerClassName={`${pill} flex-wrap whitespace-normal ${!value.dependencyIds.length ? 'text-muted' : ''}`} trigger={value.dependencyIds.length ? <>{value.dependencyIds.map(id => { const t = tasks.find(row => row.id === id); return t ? <Fragment key={id}><span className="rounded-[4px] bg-surface-3 px-[5px] py-px font-mono text-[11px]">{t.key}</span><span className="max-w-[160px] truncate">{t.title}</span></Fragment> : null; })}</> : <><Icon name="git-branch" size={13} />None</>} /> },
 ];
 if (form) return <div className="flex flex-wrap items-center gap-[6px]">{['project','status','assignee','priority','due','start','labels','repeat'].map(key => <Fragment key={key}>{entries.find(row => row.key === key)!.field}</Fragment>)}</div>;
 return <dl className={`task-property-grid mt-3 grid items-center gap-y-[2px] text-sm ${full ? 'grid-cols-[112px_minmax(0,1fr)_112px_minmax(0,1fr)]' : 'grid-cols-[112px_minmax(0,1fr)]'}`}>{entries.map(row => <Fragment key={row.key}><dt className="m-0 flex h-[30px] items-center gap-[7px] text-secondary"><Icon name={row.icon as IconName} size={14} className="text-faint" />{row.label}</dt><dd className="m-0 flex min-h-[30px] min-w-0 flex-wrap items-center gap-1">{row.field}</dd></Fragment>)}</dl>;
}
